// Two-wheel line follower: eight RC reflectance sensors, proportional steering.
const uint8_t SENSOR[8] = {2, 3, 4, 11, 12, 13, A0, A1};   // left to right
const uint8_t ENA = 5, ENB = 6;                             // PWM: left, right
const uint8_t IN1 = 7, IN2 = 8, IN3 = 9, IN4 = 10;          // direction: left, right

const int BASE = 140;       // out of 255; the pack is 7.4 V and the motors are 6 V, so stay under about 200
const float KP = 0.06;      // PWM counts per unit of position error
const unsigned int TIMEOUT_US = 2500;

int readLine() {
  long weighted = 0, total = 0;
  for (uint8_t i = 0; i < 8; i++) { pinMode(SENSOR[i], OUTPUT); digitalWrite(SENSOR[i], HIGH); }
  delayMicroseconds(10);
  unsigned long t0 = micros();
  for (uint8_t i = 0; i < 8; i++) pinMode(SENSOR[i], INPUT);
  unsigned int decay[8] = {0};
  while (micros() - t0 < TIMEOUT_US) {
    unsigned int t = micros() - t0;
    for (uint8_t i = 0; i < 8; i++) if (decay[i] == 0 && digitalRead(SENSOR[i]) == LOW) decay[i] = t;
  }
  for (uint8_t i = 0; i < 8; i++) {
    long dark = decay[i] == 0 ? TIMEOUT_US : decay[i];   // a slow decay means a dark surface: the line
    weighted += dark * (i * 1000L);
    total += dark;
  }
  return total ? (int)(weighted / total) - 3500 : 0;     // -3500 (line far left) to +3500 (far right)
}

void drive(int left, int right) {
  digitalWrite(IN1, left >= 0); digitalWrite(IN2, left < 0);
  digitalWrite(IN3, right >= 0); digitalWrite(IN4, right < 0);
  analogWrite(ENA, constrain(abs(left), 0, 255));
  analogWrite(ENB, constrain(abs(right), 0, 255));
}

void setup() {
  for (uint8_t p = 5; p <= 10; p++) pinMode(p, OUTPUT);
}

void loop() {
  int error = readLine();
  int turn = (int)(KP * error);
  drive(BASE + turn, BASE - turn);
}
